<?php require __DIR__.'/includes/auth.php';$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();$act=$_POST['act'];if($act==='save'){$id=(int)$_POST['id'];$old=null;if($id){$q=$p->prepare('SELECT image FROM reviews WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();}$img=admin_upload('image','reviews',$old);$vals=[$_POST['customer_name'],(int)$_POST['rating'],$_POST['review_text'],$img,$_POST['source'],isset($_POST['featured'])?1:0,(int)$_POST['status'],$_POST['review_date']?:null];if($id){$st=$p->prepare('UPDATE reviews SET customer_name=?,rating=?,review_text=?,image=?,source=?,featured=?,status=?,review_date=? WHERE id=?');$vals[]=$id;$st->execute($vals);}else{$p->prepare('INSERT INTO reviews(customer_name,rating,review_text,image,source,featured,status,review_date) VALUES(?,?,?,?,?,?,?,?)')->execute($vals);}header('Location: reviews.php');exit;}if($act==='delete'){$q=$p->prepare('SELECT image FROM reviews WHERE id=?');$q->execute([(int)$_POST['id']]);admin_delete_image($q->fetchColumn());$p->prepare('DELETE FROM reviews WHERE id=?')->execute([(int)$_POST['id']]);header('Location: reviews.php');exit;}}$edit=null;if(isset($_GET['id'])){$q=$p->prepare('SELECT * FROM reviews WHERE id=?');$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}$rows=$p->query('SELECT * FROM reviews ORDER BY id DESC')->fetchAll();$page_title='Reviews';require __DIR__.'/includes/header.php';?><div class="form"><h3><?= $edit?'Edit':'Add' ?> Review</h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="save"><input type="hidden" name="id" value="<?=admin_e($edit['id']??0)?>"><div class="formgrid"><div class="field"><label>Name</label><input required name="customer_name" value="<?=admin_e($edit['customer_name']??'')?>"></div><div class="field"><label>Rating</label><select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>" <?=($edit['rating']??5)==$i?'selected':''?>><?=$i?> Stars</option><?php endfor;?></select></div><div class="field full"><label>Review</label><textarea required name="review_text"><?=admin_e($edit['review_text']??'')?></textarea></div><div class="field"><label>Source</label><input name="source" value="<?=admin_e($edit['source']??'')?>"></div><div class="field"><label>Date</label><input type="date" name="review_date" value="<?=admin_e($edit['review_date']??'')?>"></div><div class="field"><label>Photo</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>Status</label><select name="status"><option value="1">Published</option><option value="0" <?=isset($edit)&&!$edit['status']?'selected':''?>>Hidden</option></select></div><div class="field"><label><input type="checkbox" name="featured" <?=($edit['featured']??0)?'checked':''?>> Featured</label></div></div><div class="actions"><button class="btn">Save Review</button></div></form></div><div class="section tablebox"><table class="table"><tr><th>Name</th><th>Rating</th><th>Review</th><th>Source</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=admin_e($r['customer_name'])?></td><td><?=$r['rating']?> ★</td><td><?=admin_e($r['review_text'])?></td><td><?=admin_e($r['source'])?></td><td><a class="btn gray" href="?id=<?=$r['id']?>">Edit</a><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn red" data-confirm="Delete review?">Delete</button></form></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>